// src/app/robots.js – robots.txt der ÖkoInvest-Website
//
// Öffentliche Seiten sind frei. Portal und API werden nicht gecrawlt
// (personenbezogene bzw. vertrauliche Inhalte, Anmeldung erforderlich).
//
// Anmeldung, Registrierung, Passwort-Reset, Einladungen, Angebote mit Code,
// Terminverwaltung, Styleguide und Entwürfe sind bewusst NICHT gesperrt: Sie
// tragen <meta name="robots" content="noindex">, und Suchmaschinen müssen die
// Seite abrufen dürfen, um das noindex zu sehen. Eine Sperre hier würde dazu
// führen, dass verlinkte URLs (z. B. /login im Footer) ohne Inhalt im Index
// landen.
//
// KI-Trainingscrawler ohne Nutzen für Suche und Antworten werden gesperrt.
// KI-Such- und Antwortcrawler (OAI-SearchBot, ChatGPT-User, PerplexityBot,
// Claude-SearchBot, Bingbot, Googlebot inkl. AI Overviews) bleiben erlaubt.
//
// Domain kommt aus SITE.url (NEXT_PUBLIC_SITE_URL) – kein fester Hostname.

import { SITE } from "@/data/site";

export default function robots() {
  return {
    rules: [
      {
        userAgent: "*",
        allow: ["/", "/_next/image"],
        disallow: ["/api/", "/portal"],
      },
      {
        userAgent: ["GPTBot", "CCBot", "Bytespider", "Google-Extended", "Meta-ExternalAgent", "cohere-ai"],
        disallow: "/",
      },
    ],
    sitemap: `${SITE.url}/sitemap.xml`,
  };
}
// src/app/sitemap.js
//
// Sitemap der ÖkoInvest-Website: alle öffentlichen Routen der Seitenlandkarte
// (docs/BRIEFING.md), alle Ratgeber-Artikel aus dem Register und – sofern das
// Plattform-Backend verfügbar ist – die öffentlichen Exposés der Projektbörse.
//
// lastModified bewusst mit festen Daten statt `new Date()`: sonst meldet jeder
// Build Google, sämtliche Seiten hätten sich geändert. Datum nur anfassen,
// wenn sich der INHALT der Seite wirklich ändert.
//
// Portal, Login/Registrierung, /angebot, /einladung, /termin/verwalten und die
// Entwürfe unter /bedingungen (noindex) gehören nicht in die Sitemap bzw. sind
// über robots.txt gesperrt. /projektboerse/anbieten ist eine indexierbare
// Landingpage (mit EN-Gegenstück) und bleibt drin.

import { alleArtikel, artikelPfad } from "@/lib/ratgeber";
import { LEXIKON_STAND } from "@/data/lexikon";
import { abs } from "@/data/site";
import { META as REGIONEN_META } from "@/data/regionen/meta";

const START = new Date("2026-09-29"); // Relaunch ÖkoInvest
const RECHT = new Date("2026-09-29"); // letzte Überarbeitung der Rechtstexte

const SEITEN = [
  // Startseite & Leistungen
