  { pfad: "/energie-live", prio: 0.7, freq: "hourly" },
  // Rechner & Werkzeuge
  { pfad: "/rechner", prio: 0.8, freq: "monthly" },
  { pfad: "/flaechencheck", prio: 0.9, freq: "monthly" },
  { pfad: "/rechner/pacht", prio: 0.8, freq: "monthly" },
  { pfad: "/rechner/agri-pv", prio: 0.8, freq: "monthly" },
