  { pfad: "/rechner/projektbewertung", prio: 0.8, freq: "monthly" },
  { pfad: "/rechner/reststrom", prio: 0.7, freq: "monthly" },
  { pfad: "/rechner/solarcarport", prio: 0.7, freq: "monthly" },
  { pfad: "/rechner/kommune", prio: 0.7, freq: "monthly" },
